const fs = require('node:fs');

function replaceOrFail(path, from, to, label) {
  const source = fs.readFileSync(path, 'utf8');
  if (!source.includes(from)) throw new Error(`Could not find ${label} in ${path}`);
  fs.writeFileSync(path, source.replace(from, to));
}

const motionPath = 'web-ui/src/mobile/mobile-voice-motion-orb.js';
replaceOrFail(motionPath, `const MAX_ROTATION_DEG = 7;\n`, `const MAX_ROTATION_DEG = 7;\nconst ORIENTATION_CHANGE_EPSILON = 0.004;\nconst ACCELERATION_NOISE_FLOOR = 0.35;\nconst ROTATION_RATE_NOISE_FLOOR = 3;\n`, 'motion thresholds');
replaceOrFail(motionPath, `export function createOrbPhysicsState() {\n  return { x: 0, y: 0, vx: 0, vy: 0, rotation: 0, vRotation: 0, shake: 0 };\n}\n\nexport function stepOrbPhysics`, `export function createOrbPhysicsState() {\n  return { x: 0, y: 0, vx: 0, vy: 0, rotation: 0, vRotation: 0, shake: 0 };\n}\n\nexport function isOrbPhysicsSettled(state, input = {}) {\n  const current = state || createOrbPhysicsState();\n  const tiltX = clamp(input?.tiltX, -1, 1);\n  const tiltY = clamp(input?.tiltY, -1, 1);\n  const targetX = tiltX * TILT_TRAVEL_X_PX;\n  const targetY = tiltY * TILT_TRAVEL_Y_PX;\n  const targetRotation = tiltX * MAX_ROTATION_DEG;\n  return Math.abs(current.x - targetX) < 0.08\n    && Math.abs(current.y - targetY) < 0.08\n    && Math.abs(current.rotation - targetRotation) < 0.05\n    && Math.abs(current.vx) < 0.15\n    && Math.abs(current.vy) < 0.15\n    && Math.abs(current.vRotation) < 0.18\n    && current.shake < 0.002\n    && Math.abs(Number(input?.impulseX) || 0) < 0.01\n    && Math.abs(Number(input?.impulseY) || 0) < 0.01\n    && Math.abs(Number(input?.rotationImpulse) || 0) < 0.01\n    && (Number(input?.shake) || 0) < 0.002;\n}\n\nexport function stepOrbPhysics`, 'physics settle helper');
replaceOrFail(motionPath, `    writeMotionStyles(activeControl, physics);\n    frameId = requestAnimationFrame(drawFrame);`, `    writeMotionStyles(activeControl, physics);\n    if (isOrbPhysicsSettled(physics, input)) {\n      frameId = 0;\n      lastFrameAt = 0;\n      return;\n    }\n    frameId = requestAnimationFrame(drawFrame);`, 'RAF settling');
replaceOrFail(motionPath, `    const mapped = mapOrientationDelta(beta, gamma, neutral.beta, neutral.gamma, screenAngle);\n    input.tiltX = mapped.x;\n    input.tiltY = mapped.y;\n    ensureFrame();`, `    const mapped = mapOrientationDelta(beta, gamma, neutral.beta, neutral.gamma, screenAngle);\n    const changed = Math.abs(mapped.x - input.tiltX) >= ORIENTATION_CHANGE_EPSILON\n      || Math.abs(mapped.y - input.tiltY) >= ORIENTATION_CHANGE_EPSILON;\n    if (!changed) return;\n    input.tiltX = mapped.x;\n    input.tiltY = mapped.y;\n    ensureFrame();`, 'orientation wake threshold');
replaceOrFail(motionPath, `  function onMotion(event) {\n    if (!activeControl?.isConnected || supportsReducedMotion()) return;\n    const acceleration = event?.acceleration;\n    if (acceleration) {\n      const mapped = mapAccelerationToScreen(acceleration, currentScreenAngle());\n      input.impulseX += clamp(mapped.x, -14, 14);\n      input.impulseY += clamp(-mapped.y, -14, 14);\n      input.shake = Math.max(input.shake, computeShakeEnergy(acceleration));\n    }\n    const rotationRate = event?.rotationRate;\n    if (rotationRate) {\n      input.rotationImpulse += Number(rotationRate.gamma ?? rotationRate.alpha) || 0;\n    }\n    ensureFrame();\n  }`, `  function onMotion(event) {\n    if (!activeControl?.isConnected || supportsReducedMotion()) return;\n    let shouldWake = false;\n    const acceleration = event?.acceleration;\n    if (acceleration) {\n      const mapped = mapAccelerationToScreen(acceleration, currentScreenAngle());\n      const impulseX = Math.abs(mapped.x) >= ACCELERATION_NOISE_FLOOR ? clamp(mapped.x, -14, 14) : 0;\n      const impulseY = Math.abs(mapped.y) >= ACCELERATION_NOISE_FLOOR ? clamp(-mapped.y, -14, 14) : 0;\n      const shake = computeShakeEnergy(acceleration);\n      if (impulseX || impulseY || shake > 0) {\n        input.impulseX += impulseX;\n        input.impulseY += impulseY;\n        input.shake = Math.max(input.shake, shake);\n        shouldWake = true;\n      }\n    }\n    const rotationRate = event?.rotationRate;\n    if (rotationRate) {\n      const rotationImpulse = Number(rotationRate.gamma ?? rotationRate.alpha) || 0;\n      if (Math.abs(rotationImpulse) >= ROTATION_RATE_NOISE_FLOOR) {\n        input.rotationImpulse += rotationImpulse;\n        shouldWake = true;\n      }\n    }\n    if (shouldWake) ensureFrame();\n  }`, 'motion noise floor');
replaceOrFail(motionPath, `  document.addEventListener('pointerdown', handleGesture, { capture: true, passive: true });\n  document.addEventListener('touchstart', handleGesture, { capture: true, passive: true });`, `  // WebKit grants transient activation for a finger on pointerup/touchend,\n  // not pointerdown/touchstart. Request sensor access at gesture completion.\n  document.addEventListener('pointerup', handleGesture, { capture: true, passive: true });\n  document.addEventListener('touchend', handleGesture, { capture: true, passive: true });`, 'iOS permission gesture listeners');
replaceOrFail(motionPath, `      document.removeEventListener('pointerdown', handleGesture, true);\n      document.removeEventListener('touchstart', handleGesture, true);`, `      document.removeEventListener('pointerup', handleGesture, true);\n      document.removeEventListener('touchend', handleGesture, true);`, 'iOS permission gesture cleanup');

replaceOrFail('web-ui/src/mobile/mobile-voice-page.js', `void context.mountThinkingOrbWhenReady(thinkingOrbHost, { state: 'thinking', size: 64, theme: 'auto' })`, `void context.mountThinkingOrbWhenReady(thinkingOrbHost, { state: 'thinking', size: 64, theme: 'auto', speed: 0.5 })`, 'Voice orb speed');

replaceOrFail('web-ui/src/mobile/mobile-pages.js', `    pc.addEventListener('connectionstatechange', () => {\n      if (['closed', 'failed', 'disconnected'].includes(pc.connectionState) && __pmRealtimeAgent.conn?.pc === pc) {\n        _notifyMobileVoiceAgentConnection('reconnecting', { sessionId: sid, reason: pc.connectionState });\n        _stopMobileRealtimeAgentSession();\n      }\n    });`, `    let transientDisconnectTimer = null;\n    const clearTransientDisconnectTimer = () => {\n      if (transientDisconnectTimer) clearTimeout(transientDisconnectTimer);\n      transientDisconnectTimer = null;\n    };\n    pc.addEventListener('connectionstatechange', () => {\n      if (__pmRealtimeAgent.conn?.pc !== pc) {\n        clearTransientDisconnectTimer();\n        return;\n      }\n      const state = pc.connectionState;\n      if (state === 'connected') {\n        clearTransientDisconnectTimer();\n        return;\n      }\n      if (state === 'disconnected') {\n        if (!transientDisconnectTimer) {\n          transientDisconnectTimer = setTimeout(() => {\n            transientDisconnectTimer = null;\n            if (__pmRealtimeAgent.conn?.pc !== pc || pc.connectionState !== 'disconnected') return;\n            _notifyMobileVoiceAgentConnection('reconnecting', { sessionId: sid, reason: 'rtc_disconnected_timeout' });\n            _stopMobileRealtimeAgentSession();\n          }, 5000);\n        }\n        return;\n      }\n      if (state === 'closed' || state === 'failed') {\n        clearTransientDisconnectTimer();\n        _notifyMobileVoiceAgentConnection('reconnecting', { sessionId: sid, reason: state });\n        _stopMobileRealtimeAgentSession();\n      }\n    });`, 'realtime agent transient disconnect handling');

const motionTestPath = 'scripts/test-mobile-voice-motion-orb.mjs';
let motionTest = fs.readFileSync(motionTestPath, 'utf8');
if (!motionTest.includes('isOrbPhysicsSettled')) {
  motionTest = motionTest.replace(`import assert from 'node:assert/strict';\n`, `import assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\n`);
  motionTest = motionTest.replace(`  createOrbPhysicsState,\n`, `  createOrbPhysicsState,\n  isOrbPhysicsSettled,\n`);
  motionTest = motionTest.replace(`let physics = createOrbPhysicsState();\n`, `let physics = createOrbPhysicsState();\nassert.equal(isOrbPhysicsSettled(physics, { tiltX: 0, tiltY: 0 }), true, 'an untouched neutral orb should not keep an animation frame alive');\n`);
  motionTest = motionTest.replace(`assert.ok(physics.shake < 1, 'shake scale should decay instead of sticking');\n`, `assert.ok(physics.shake < 1, 'shake scale should decay instead of sticking');\nassert.equal(isOrbPhysicsSettled(physics, { tiltX: 1, tiltY: 0 }), false, 'an orb with residual spring energy should keep animating');\nfor (let i = 0; i < 240; i += 1) physics = stepOrbPhysics(physics, { tiltX: 1, tiltY: 0 }, 1 / 60);\nassert.equal(isOrbPhysicsSettled(physics, { tiltX: 1, tiltY: 0 }), true, 'settled spring physics should release the requestAnimationFrame loop');\n\nconst motionSource = readFileSync(new URL('../web-ui/src/mobile/mobile-voice-motion-orb.js', import.meta.url), 'utf8');\nassert.match(motionSource, /addEventListener\\('pointerup', handleGesture/, 'touch pointerup must request iOS motion permission');\nassert.match(motionSource, /addEventListener\\('touchend', handleGesture/, 'touchend must request iOS motion permission');\nassert.doesNotMatch(motionSource, /addEventListener\\('touchstart', handleGesture/, 'touchstart is not a WebKit transient-activation event');\nconst voicePageSource = readFileSync(new URL('../web-ui/src/mobile/mobile-voice-page.js', import.meta.url), 'utf8');\nassert.match(voicePageSource, /size: 64, theme: 'auto', speed: 0\\.5/, 'mobile Voice orb should run its autonomous animation at half speed');\n`);
  fs.writeFileSync(motionTestPath, motionTest);
}

fs.writeFileSync('scripts/test-mobile-realtime-transient-disconnect.mjs', `import assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\n\nconst source = readFileSync(new URL('../web-ui/src/mobile/mobile-pages.js', import.meta.url), 'utf8');\nconst anchor = source.indexOf("pc.addEventListener('connectionstatechange', () => logState('connectionstatechange'))");\nassert.ok(anchor >= 0, 'realtime agent connection-state logging hook should exist');\nconst block = source.slice(anchor, anchor + 4200);\nassert.match(block, /let transientDisconnectTimer = null/, 'realtime agent should track a transient disconnect grace timer');\nassert.match(block, /state === 'disconnected'/, 'disconnected should have a dedicated transient path');\nassert.match(block, /rtc_disconnected_timeout/, 'only an expired disconnect grace period should enter reconnect teardown');\nassert.match(block, /}, 5000\\)/, 'transient disconnect should receive a five-second recovery window');\nassert.match(block, /state === 'connected'[\\s\\S]*clearTransientDisconnectTimer/, 'a recovered peer connection should cancel teardown');\nassert.match(block, /state === 'closed' \\|\\| state === 'failed'/, 'closed and failed should remain terminal');\nassert.doesNotMatch(block, /\\['closed', 'failed', 'disconnected'\\]/, 'disconnected must not share the immediate terminal path');\nconsole.log('mobile realtime transient disconnect contract: ok');\n`);
